function unwindBrackets(s: string): string {
  const stack: string[][] = [[]];
  for (const ch of s) {
    if (ch === "(") stack.push([]);
    else if (ch === ")") {
      const inner = stack.pop()!.reverse();
      stack[stack.length - 1].push(...inner);
    } else stack[stack.length - 1].push(ch);
  }
  return stack[0].join("");
}

