function unwindBrackets(s: string): string {
  const n = s.length, pair = new Array<number>(n).fill(-1), open: number[] = [];
  for (let i = 0; i < n; i++) {
    if (s[i] === "(") open.push(i);
    else if (s[i] === ")") { const j = open.pop()!; pair[i] = j; pair[j] = i; }
  }
  const out: string[] = [];
  for (let i = 0, d = 1; i < n; i += d) {
    if (s[i] === "(" || s[i] === ")") { i = pair[i]; d = -d; }
    else out.push(s[i]);
  }
  return out.join("");
}

