class Solution:
    def unwindBrackets(self, s: str) -> str:
        n = len(s)
        pair, open_ = [-1] * n, []
        for i, ch in enumerate(s):
            if ch == "(":
                open_.append(i)
            elif ch == ")":
                j = open_.pop()
                pair[i], pair[j] = j, i
        out, i, d = [], 0, 1
        while i < n:
            if s[i] in "()":
                i, d = pair[i], -d
            else:
                out.append(s[i])
            i += d
        return "".join(out)

